14	// ============================================================================
15	// perf.cpp — vortex2.h MPM performance-counter report.
16	//
17	// vx_device_dump_perf walks the per-core / cluster / cache MPM counters via
18	// the public vx_device_query + vx_device_mpm_query primitives and prints a
19	// formatted report. Profiling class is selected by VORTEX_PROFILING.
20	// ============================================================================
21	
