41	class ProfilingMode {
42	public:
43	  ProfilingMode() : mpm_class_(0) {
44	    auto profiling_s = getenv("VORTEX_PROFILING");
45	    if (profiling_s) {
46	      mpm_class_ = std::atoi(profiling_s);
47	    }
48	  }
49	
50	  ~ProfilingMode() {}
51	
52	  int mpm_class() const {
53	    return mpm_class_;
54	  }
55	
56	private:
57	  int mpm_class_;
58	};
59	
60	static int get_profiling_mode() {
61	  static ProfilingMode gProfilingMode;
62	  return gProfilingMode.mpm_class();
63	}
