65	static inline double safe_div(double num, double den) {
66	  return (den == 0.0) ? 0.0 : (num / den);
67	}
68	
69	static inline int calc_percent(uint64_t part, uint64_t total) {
70	  return (total == 0) ? 0 : (int)std::lround(safe_div((double)part, (double)total) * 100.0);
71	}
72	
73	static inline int calc_ratio(uint64_t misses, uint64_t accesses) {
74	  if (accesses == 0)
75	    return 0;
76	  double miss_rate = safe_div((double)misses, (double)accesses);
77	  return (int)std::lround((1.0 - miss_rate) * 100.0);
78	}
79	
80	static inline int calc_utility(uint64_t useful, uint64_t stalls) {
81	  return calc_percent(useful, useful + stalls);
82	}
83	
84	static inline double bytes_to_GB(uint64_t bytes) {
85	  return (double)bytes / 1e9;
86	}
