88	static inline void perf_print_core(FILE *stream, int core_id, const char *fmt, ...) {
89	  std::va_list args;
90	  va_start(args, fmt);
91	  std::fprintf(stream, "PERF: core%d: ", core_id);
92	  std::vfprintf(stream, fmt, args);
93	  std::fprintf(stream, "\n");
94	  va_end(args);
95	}
96	
97	static inline void perf_print(FILE *stream, const char *fmt, ...) {
98	  std::va_list args;
99	  va_start(args, fmt);
100	  std::fprintf(stream, "PERF: ");
101	  std::vfprintf(stream, fmt, args);
102	  std::fprintf(stream, "\n");
103	  va_end(args);
104	}
