164	struct Metric {
165	  const char *label;
166	  int value;
167	  bool enabled;
168	};
169	
170	static void print_metric_list(FILE *stream, const char *category, int core_id, const std::vector<Metric> &metrics) {
171	  std::stringstream ss;
172	  ss << category << ": ";
173	  bool first = true;
174	  for (const auto &m : metrics) {
175	    if (m.enabled) {
176	      if (!first)
177	        ss << ", ";
178	      ss << m.label << "=" << m.value << "%";
179	      first = false;
180	    }
181	  }
182	
183	  if (core_id >= 0) {
184	    perf_print_core(stream, core_id, "%s", ss.str().c_str());
185	  } else {
186	    perf_print(stream, "%s", ss.str().c_str());
187	  }
188	}
