190	// Read a single 64-bit MPM performance counter. `addr` is an MPM CSR in
191	// [VX_CSR_MPM_BASE, VX_CSR_MPM_BASE+32); `core_id == 0xffffffff` sums the
192	// counter across all cores. The 64-bit value is assembled from two 32-bit
193	// DCR half-reads (lo at csr_id, hi at csr_id+32), each packed with
194	// mpm_class|csr_id|core onto the DCR bus. Submits straight to the CP — the
195	// public vx_enqueue_dcr_read cannot carry the MPM tag.
196	extern "C" vx_result_t vx_device_mpm_query(vx_device_h dev, uint32_t mpm_class,
197	                                           uint32_t addr, uint32_t core_id,
198	                                           uint64_t* out_value) {
199	  if (!dev) return VX_ERR_INVALID_HANDLE;
200	  if (!out_value) return VX_ERR_INVALID_VALUE;
201	  if (!(addr >= VX_CSR_MPM_BASE && addr < (VX_CSR_MPM_BASE + 32)))
202	    return VX_ERR_INVALID_VALUE;
203	
204	  vx::Device* device = vx::to_device(dev);
205	  const uint32_t csr_id  = addr - VX_CSR_MPM_BASE;
206	  const uint32_t clss_sh = mpm_class << (16 + 6);
207	
208	  auto read_one = [&](uint32_t cid, uint64_t* out) -> vx_result_t {
209	    uint32_t lo = 0, hi = 0;
210	    uint32_t tag_lo = clss_sh | ((csr_id << 16) | cid);
211	    uint32_t tag_hi = clss_sh | (((csr_id + 32) << 16) | cid);
212	    auto r = device->cp_submit_dcr_read(VX_DCR_BASE_MPM_VALUE, tag_lo, &lo);
213	    if (r != VX_SUCCESS) return r;
214	    r = device->cp_submit_dcr_read(VX_DCR_BASE_MPM_VALUE, tag_hi, &hi);
215	    if (r != VX_SUCCESS) return r;
216	    *out = ((uint64_t)hi << 32) | lo;
217	    return VX_SUCCESS;
218	  };
219	
220	  if (core_id == 0xffffffff) {
221	    uint64_t num_cores = 0;
222	    auto r = device->query_caps(VX_CAPS_NUM_CORES, &num_cores);
223	    if (r != VX_SUCCESS) return r;
224	    uint64_t sum = 0;
225	    for (uint32_t i = 0; i < (uint32_t)num_cores; ++i) {
226	      uint64_t cur = 0;
227	      r = read_one(i, &cur);
228	      if (r != VX_SUCCESS) return r;
229	      sum += cur;
230	    }
231	    *out_value = sum;
232	    return VX_SUCCESS;
233	  }
234	  return read_one(core_id, out_value);
235	}
