237	extern "C" vx_result_t vx_device_dump_perf(vx_device_h hdevice, FILE *stream) {
238	  if (nullptr == stream)
239	    stream = stdout;
240	
241	  uint64_t num_cores = 0;
242	  uint64_t num_clusters = 0;
243	  uint64_t socket_size = 0;
244	  uint64_t num_warps = 0;
245	  uint64_t num_threads = 0;
246	  uint64_t issue_width = 0;
247	  uint64_t isa_flags = 0;
248	  uint64_t clock_mhz = 0;
249	  uint64_t peak_mem_bw_MBps = 0;
250	  uint64_t vm_support = 0;
251	
252	  const auto mpm_class = get_profiling_mode();
253	
254	  CHECK_ERR(vx_device_query(hdevice, VX_CAPS_NUM_CORES, &num_cores), { return err; });
255	  CHECK_ERR(vx_device_query(hdevice, VX_CAPS_NUM_CLUSTERS, &num_clusters), { return err; });
256	  CHECK_ERR(vx_device_query(hdevice, VX_CAPS_SOCKET_SIZE, &socket_size), { return err; });
257	  CHECK_ERR(vx_device_query(hdevice, VX_CAPS_NUM_WARPS, &num_warps), { return err; });
258	  CHECK_ERR(vx_device_query(hdevice, VX_CAPS_NUM_THREADS, &num_threads), { return err; });
259	  CHECK_ERR(vx_device_query(hdevice, VX_CAPS_ISSUE_WIDTH, &issue_width), { return err; });
260	  CHECK_ERR(vx_device_query(hdevice, VX_CAPS_ISA_FLAGS, &isa_flags), { return err; });
261	  CHECK_ERR(vx_device_query(hdevice, VX_CAPS_CLOCK_RATE, &clock_mhz), { return err; });
262	  CHECK_ERR(vx_device_query(hdevice, VX_CAPS_PEAK_MEM_BW, &peak_mem_bw_MBps), { return err; });
263	  CHECK_ERR(vx_device_query(hdevice, VX_CAPS_VM_SUPPORT, &vm_support), { return err; });
264	
265	  // VM is a runtime device property — gate the MMU/TLB perf counters on it.
266	  const bool vm_enabled = (vm_support != 0);
267	
268	  const bool icache_en = (isa_flags & VX_ISA_EXT_ICACHE) != 0;
269	  const bool dcache_en = (isa_flags & VX_ISA_EXT_DCACHE) != 0;
270	  const bool l2_en = (isa_flags & VX_ISA_EXT_L2CACHE) != 0;
271	  const bool l3_en = (isa_flags & VX_ISA_EXT_L3CACHE) != 0;
272	  const bool lmem_en = (isa_flags & VX_ISA_EXT_LMEM) != 0;
273	
274	  const bool fpu_en = (isa_flags & VX_ISA_STD_F) != 0;
275	  const bool tcu_en = (isa_flags & VX_ISA_EXT_TCU) != 0;
276	  const bool tex_en = (isa_flags & VX_ISA_EXT_TEX) != 0;
277	  const bool raster_en = (isa_flags & VX_ISA_EXT_RASTER) != 0;
278	  const bool om_en = (isa_flags & VX_ISA_EXT_OM) != 0;
279	
280	  std::vector<CoreCounters> cores(num_cores);
281	  uint64_t total_instrs = 0;
282	  uint64_t max_cycles = 0;
283	
284	  for (uint32_t core_id = 0; core_id < num_cores; ++core_id) {
285	    auto &c = cores[core_id];
286	
287	    CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MCYCLE, core_id, &c.cycles), { return err; });
288	    CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MINSTRET, core_id, &c.instrs), { return err; });
289	
290	    total_instrs += c.instrs;
291	    max_cycles = std::max<uint64_t>(max_cycles, c.cycles);
292	  }
293	
294	  switch (mpm_class) {
295	  case VX_DCR_MPM_CLASS_BASE:
296	    break;
297	
298	  case VX_DCR_MPM_CLASS_CORE: {
299	    CoreCounters tot;
300	
301	    for (uint32_t core_id = 0; core_id < num_cores; ++core_id) {
302	      auto &c = cores[core_id];
303	
304	      // Query Core Specifics
305	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_SCHED_IDLE, core_id, &c.sched_idle), { return err; });
306	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_ACTIVE_WARPS, core_id, &c.active_warps), { return err; });
307	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_STALLED_WARPS, core_id, &c.stalled_warps), { return err; });
308	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_ISSUED_WARPS, core_id, &c.issued_warps), { return err; });
309	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_ISSUED_THREADS, core_id, &c.issued_threads), { return err; });
310	
311	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_STALL_FETCH, core_id, &c.stall_fetch), { return err; });
312	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_STALL_IBUF, core_id, &c.stall_ibuf), { return err; });
313	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_STALL_SCRB, core_id, &c.stall_scrb), { return err; });
314	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_STALL_OPDS, core_id, &c.stall_opds), { return err; });
315	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_STALL_ALU, core_id, &c.stall_alu), { return err; });
316	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_STALL_FPU, core_id, &c.stall_fpu), { return err; });
317	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_STALL_LSU, core_id, &c.stall_lsu), { return err; });
318	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_STALL_SFU, core_id, &c.stall_sfu), { return err; });
319	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_STALL_TCU, core_id, &c.stall_tcu), { return err; });
320	
321	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_INSTR_ALU, core_id, &c.instr_alu), { return err; });
322	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_INSTR_FPU, core_id, &c.instr_fpu), { return err; });
323	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_INSTR_LSU, core_id, &c.instr_lsu), { return err; });
324	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_INSTR_SFU, core_id, &c.instr_sfu), { return err; });
325	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_INSTR_TCU, core_id, &c.instr_tcu), { return err; });
326	
327	      // Branches
328	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_BRANCHES, core_id, &c.branches), { return err; });
329	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_DIVERGENCE, core_id, &c.divergence), { return err; });
330	
331	      // Memory (front-end + LSU)
332	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_IFETCHES, core_id, &c.ifetches), { return err; });
333	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_IFETCH_LT, core_id, &c.ifetch_lt), { return err; });
334	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_LOADS, core_id, &c.loads), { return err; });
335	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_LOAD_LT, core_id, &c.load_lt), { return err; });
336	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_STORES, core_id, &c.stores), { return err; });
337	
338	      if (num_cores > 1) {
339	        // Per-Core report
340	        const uint64_t cycles = c.cycles;
341	        const uint64_t cycles_wide = cycles * issue_width;
342	        const double ipc = safe_div((double)c.instrs, (double)cycles);
343	
344	        // Scheduler report
345	        const int idle_pct = calc_percent(c.sched_idle, cycles);
346	        const double avg_occ = safe_div((double)c.active_warps, (double)cycles);
347	        const int occ_pct = (int)std::lround(safe_div(avg_occ, (double)num_warps) * 100.0);
348	        const double warp_eff = safe_div((double)c.issued_threads, (double)c.issued_warps);
349	        const int warp_eff_pct = (int)std::lround(safe_div(warp_eff, (double)num_threads) * 100.0);
350	        perf_print_core(stream, core_id, "scheduler: idle=%d%%, occupancy=%.1f (%d%%), simt_util=%.1f (%d%%)",
351	                        idle_pct, avg_occ, occ_pct, warp_eff, warp_eff_pct);
352	
353	        // Pipeline stalls report
354	        std::vector<Metric> stall_metrics = {
355	          {"fetch", calc_percent(c.stall_fetch, cycles), true},
356	          {"ibuf", calc_percent(c.stall_ibuf, cycles), true},
357	          {"scrb", calc_percent(c.stall_scrb, cycles_wide), true},
358	          {"opds", calc_percent(c.stall_opds, cycles_wide), true},
359	          {"alu", calc_percent(c.stall_alu, cycles_wide), true},
360	          {"lsu", calc_percent(c.stall_lsu, cycles_wide), true},
361	          {"sfu", calc_percent(c.stall_sfu, cycles_wide), true},
362	          {"fpu", calc_percent(c.stall_fpu, cycles_wide), fpu_en},
363	          {"tcu", calc_percent(c.stall_tcu, cycles_wide), tcu_en}
364	        };
365	        print_metric_list(stream, "stalls", core_id, stall_metrics);
366	
367	        // Instruction mix report
368	        std::vector<Metric> mix_metrics = {
369	          {"alu", calc_percent(c.instr_alu, c.instrs), true},
370	          {"lsu", calc_percent(c.instr_lsu, c.instrs), true},
371	          {"sfu", calc_percent(c.instr_sfu, c.instrs), true},
372	          {"fpu", calc_percent(c.instr_fpu, c.instrs), fpu_en},
373	          {"tcu", calc_percent(c.instr_tcu, c.instrs), tcu_en}
374	        };
375	        print_metric_list(stream, "inst_mix", core_id, mix_metrics);
376	
377	        // Branch report
378	        int div_pct = calc_percent(c.divergence, c.branches);
379	        perf_print_core(stream, core_id, "branches: total=%" PRIu64 ", divergent=%" PRIu64 " (rate=%d%%)",
380	                        c.branches, c.divergence, div_pct);
381	
382	        // Memory report
383	        const double ifetch_avg_lt = safe_div((double)c.ifetch_lt, (double)c.ifetches);
384	        const double load_avg_lt = safe_div((double)c.load_lt, (double)c.loads);
385	        perf_print_core(stream, core_id, "memory: ifetch_lat=%.2f, load_lat=%.2f, loads=%" PRIu64 ", stores=%" PRIu64,
386	                        ifetch_avg_lt, load_avg_lt, c.loads, c.stores);
387	
388	        perf_print_core(stream, core_id, "instrs=%" PRIu64 ", cycles=%" PRIu64 ", IPC=%.3f", c.instrs, c.cycles, ipc);
389	      }
390	
391	      // Accumulate
392	      tot.cycles += c.cycles;
393	      tot.instrs += c.instrs;
394	      tot.sched_idle += c.sched_idle;
395	      tot.active_warps += c.active_warps;
396	      tot.stalled_warps += c.stalled_warps;
397	      tot.issued_warps += c.issued_warps;
398	      tot.issued_threads += c.issued_threads;
399	
400	      tot.stall_fetch += c.stall_fetch;
401	      tot.stall_ibuf += c.stall_ibuf;
402	      tot.stall_scrb += c.stall_scrb;
403	      tot.stall_opds += c.stall_opds;
404	      tot.stall_alu += c.stall_alu;
405	      tot.stall_fpu += c.stall_fpu;
406	      tot.stall_lsu += c.stall_lsu;
407	      tot.stall_sfu += c.stall_sfu;
408	      tot.stall_tcu += c.stall_tcu;
409	
410	      tot.instr_alu += c.instr_alu;
411	      tot.instr_fpu += c.instr_fpu;
412	      tot.instr_lsu += c.instr_lsu;
413	      tot.instr_sfu += c.instr_sfu;
414	      tot.instr_tcu += c.instr_tcu;
415	
416	      tot.branches += c.branches;
417	      tot.divergence += c.divergence;
418	
419	      tot.ifetches += c.ifetches;
420	      tot.ifetch_lt += c.ifetch_lt;
421	      tot.loads += c.loads;
422	      tot.load_lt += c.load_lt;
423	      tot.stores += c.stores;
424	    }
425	
426	    // Core Summary
427	    uint64_t tot_cycles_wide = tot.cycles * issue_width;
428	
429	    // Scheduler report
430	    const int tot_idle_pct = calc_percent(tot.sched_idle, tot.cycles);
431	    const double tot_avg_occ = safe_div((double)tot.active_warps, (double)tot.cycles);
432	    const int tot_occ_pct = (int)std::lround(safe_div(tot_avg_occ, (double)num_warps) * 100.0);
433	    const double tot_warp_eff = safe_div((double)tot.issued_threads, (double)tot.issued_warps);
434	    const int tot_warp_eff_pct = (int)std::lround(safe_div(tot_warp_eff, (double)num_threads) * 100.0);
435	    perf_print(stream, "scheduler: idle=%d%%, occupancy=%.1f (%d%%), simt_util=%.1f (%d%%)",
