708	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_RCACHE_MSHR_ST, core_id, &mst), { return err; });
709	
710	      double avg_lat = safe_div((double)lat, (double)reads);
711	      perf_print_core(stream, core_id,
712	        "raster: reads=%" PRIu64 ", avg_lat=%.1f cyc, stalls=%" PRIu64 "; rcache: reqs=%" PRIu64 ", miss=%" PRIu64 " (hit=%d%%), bank_st=%" PRIu64 " (utility=%d%%)",
713	        reads, avg_lat, st, r, mr, calc_ratio(mr, r), bst, calc_utility(r, bst));
714	      tot_reads += reads; tot_lat += lat; tot_st += st;
715	      rcache_tot.reads += r; rcache_tot.miss_r += mr; rcache_tot.bank_st += bst; rcache_tot.mshr_st += mst;
716	    }
717	    double tot_avg_lat = safe_div((double)tot_lat, (double)tot_reads);
718	    perf_print(stream,
719	      "raster: total_reads=%" PRIu64 ", avg_lat=%.1f cyc, total_stalls=%" PRIu64
720	      "; rcache: total_reqs=%" PRIu64 ", miss=%" PRIu64 " (hit=%d%%), bank_st=%" PRIu64 " (utility=%d%%), mshr_st=%" PRIu64 " (utility=%d%%)",
721	      tot_reads, tot_avg_lat, tot_st,
722	      rcache_tot.reads, rcache_tot.miss_r, calc_ratio(rcache_tot.miss_r, rcache_tot.reads),
723	      rcache_tot.bank_st, calc_utility(rcache_tot.reads, rcache_tot.bank_st),
724	      rcache_tot.mshr_st, calc_utility(rcache_tot.miss_r, rcache_tot.mshr_st));
725	  } break;
726	
727	  case VX_DCR_MPM_CLASS_OM: {
728	    if (!om_en) {
729	      perf_print(stream, "OM not supported");
730	      break;
731	    }
732	    uint64_t tot_reads = 0, tot_writes = 0, tot_lat = 0, tot_st = 0;
733	    CacheCounters ocache_tot;
734	    for (uint32_t core_id = 0; core_id < num_cores; ++core_id) {
735	      uint64_t reads = 0, writes = 0, lat = 0, st = 0;
736	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_OM_READS,  core_id, &reads),  { return err; });
737	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_OM_WRITES, core_id, &writes), { return err; });
738	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_OM_LAT,    core_id, &lat),    { return err; });
739	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_OM_ST,     core_id, &st),     { return err; });
740	      uint64_t r = 0, w = 0, mr = 0, mw = 0, bst = 0, mst = 0;
741	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_OCACHE_READS,   core_id, &r),   { return err; });
742	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_OCACHE_WRITES,  core_id, &w),   { return err; });
743	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_OCACHE_MISS_R,  core_id, &mr),  { return err; });
744	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_OCACHE_MISS_W,  core_id, &mw),  { return err; });
745	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_OCACHE_BANK_ST, core_id, &bst), { return err; });
746	      CHECK_ERR(vx_device_mpm_query(hdevice, mpm_class, VX_CSR_MPM_OCACHE_MSHR_ST, core_id, &mst), { return err; });
747	
748	      double avg_lat = safe_div((double)lat, (double)reads);
749	      perf_print_core(stream, core_id,
750	        "om: reads=%" PRIu64 ", writes=%" PRIu64 ", avg_lat=%.1f cyc, stalls=%" PRIu64
751	        "; ocache: reqs=%" PRIu64 ", miss_r=%" PRIu64 " (hit=%d%%), miss_w=%" PRIu64 " (hit=%d%%), bank_st=%" PRIu64 " (utility=%d%%)",
752	        reads, writes, avg_lat, st,
753	        r + w, mr, calc_ratio(mr, r), mw, calc_ratio(mw, w), bst, calc_utility(r + w, bst));
754	      tot_reads += reads; tot_writes += writes; tot_lat += lat; tot_st += st;
755	      ocache_tot.reads += r; ocache_tot.writes += w;
756	      ocache_tot.miss_r += mr; ocache_tot.miss_w += mw;
757	      ocache_tot.bank_st += bst; ocache_tot.mshr_st += mst;
758	    }
759	    double tot_avg_lat = safe_div((double)tot_lat, (double)tot_reads);
760	    perf_print(stream,
761	      "om: total_reads=%" PRIu64 ", total_writes=%" PRIu64 ", avg_lat=%.1f cyc, total_stalls=%" PRIu64
762	      "; ocache: total_reqs=%" PRIu64 ", miss_r=%" PRIu64 " (hit=%d%%), miss_w=%" PRIu64 " (hit=%d%%), bank_st=%" PRIu64 " (utility=%d%%), mshr_st=%" PRIu64 " (utility=%d%%)",
763	      tot_reads, tot_writes, tot_avg_lat, tot_st,
764	      ocache_tot.reads + ocache_tot.writes,
765	      ocache_tot.miss_r, calc_ratio(ocache_tot.miss_r, ocache_tot.reads),
766	      ocache_tot.miss_w, calc_ratio(ocache_tot.miss_w, ocache_tot.writes),
767	      ocache_tot.bank_st, calc_utility(ocache_tot.reads + ocache_tot.writes, ocache_tot.bank_st),
768	      ocache_tot.mshr_st, calc_utility(ocache_tot.miss_r + ocache_tot.miss_w, ocache_tot.mshr_st));
769	  } break;
770	
771	  default:
772	    fprintf(stream, "Error: invalid profiling class: %d)", mpm_class);
773	    return VX_ERR_INVALID_VALUE;
774	  }
775	
776	  double global_ipc = safe_div((double)total_instrs, (double)max_cycles);
777	  perf_print(stream, "instrs=%" PRIu64 ", cycles=%" PRIu64 ", IPC=%.3f", total_instrs, max_cycles, global_ipc);
778	
779	  std::fflush(stream);
780	  return VX_SUCCESS;
781	}

