8	// sgemm — vortex2.h-native regression test.
9	//
10	// 3 fire-and-forget uploads (A, B, args) + 1 launch + 1 read gated on
11	// launch + 1 trailing wait. The per-queue worker thread serializes
12	// everything in FIFO order.
13	
14	#include <vortex2.h>
15	#include "common.h"
16	
17	#include <chrono>
18	#include <cmath>
19	#include <cstdint>
20	#include <cstdio>
21	#include <cstdlib>
22	#include <iostream>
23	#include <unistd.h>
24	#include <vector>
25	
26	#define CHECK(expr) do { \
27	    vx_result_t _r = (expr); \
28	    if (_r != VX_SUCCESS) { \
29	        std::fprintf(stderr, "FAIL %s:%d: '%s' returned %s\n", \
30	                     __FILE__, __LINE__, #expr, vx_result_string(_r)); \
31	        std::exit(1); \
32	    } \
33	} while (0)
34	
35	namespace {
36	const char* kernel_file = "kernel.vxbin";
37	uint32_t    size        = 64;
38	
39	void parse_args(int argc, char** argv) {
40	    int c;
41	    while ((c = getopt(argc, argv, "n:k:h")) != -1) {
42	        switch (c) {
43	            case 'n': size        = std::atoi(optarg); break;
44	            case 'k': kernel_file = optarg;            break;
45	            default:
46	                std::cout << "Usage: [-k kernel] [-n size] [-h]" << std::endl;
47	                std::exit(c == 'h' ? 0 : -1);
48	        }
49	    }
50	}
51	
52	bool float_eq(float a, float b) {
53	    union fi { float f; int32_t i; };
54	    fi fa{a}, fb{b};
55	    return std::abs(fa.i - fb.i) <= 6;
56	}
57	
58	void matmul_cpu(TYPE* out, const TYPE* A, const TYPE* B, uint32_t n) {
59	    for (uint32_t r = 0; r < n; ++r)
60	        for (uint32_t c = 0; c < n; ++c) {
61	            TYPE s(0);
62	            for (uint32_t e = 0; e < n; ++e) s += A[r*n + e] * B[e*n + c];
63	            out[r*n + c] = s;
64	        }
65	}
66	} // namespace
67	
68	int main(int argc, char** argv) {
69	    parse_args(argc, argv);
70	    std::srand(50);
71	
72	    const uint32_t size_sq  = size * size;
73	    const uint64_t buf_size = size_sq * sizeof(TYPE);
74	    std::cout << "sgemm vortex2: " << size << "x" << size << std::endl;
75	
76	    vx_device_h dev = nullptr;
77	    CHECK(vx_device_open(0, &dev));
78	
79	    vx_queue_info_t qi = { sizeof(qi), nullptr, VX_QUEUE_PRIORITY_NORMAL, 0 };
80	    vx_queue_h q = nullptr;
81	    CHECK(vx_queue_create(dev, &qi, &q));
82	
83	    const uint32_t global_dim[2] = {size, size};
84	    uint32_t grid[2], block[2];
85	    CHECK(vx_device_max_occupancy_grid(dev, 2, global_dim, grid, block));
86	    if ((size % block[0]) || (size % block[1])) {
87	        std::cerr << "matrix size " << size << " must divide block "
88	                  << block[0] << "x" << block[1] << std::endl;
89	        return -1;
90	    }
91	
92	    vx_buffer_h A_buf=nullptr, B_buf=nullptr, C_buf=nullptr;
93	    CHECK(vx_buffer_create(dev, buf_size, VX_MEM_READ,  &A_buf));
94	    CHECK(vx_buffer_create(dev, buf_size, VX_MEM_READ,  &B_buf));
95	    CHECK(vx_buffer_create(dev, buf_size, VX_MEM_WRITE, &C_buf));
96	
97	    vx_module_h mod = nullptr;
98	    vx_kernel_h kern = nullptr;
99	    CHECK(vx_module_load_file(dev, kernel_file, &mod));
100	    CHECK(vx_module_get_kernel(mod, "main", &kern));
101	
102	    kernel_arg_t kernel_arg{};
103	    kernel_arg.size = size;
104	    CHECK(vx_buffer_address(A_buf, &kernel_arg.A_addr));
105	    CHECK(vx_buffer_address(B_buf, &kernel_arg.B_addr));
106	    CHECK(vx_buffer_address(C_buf, &kernel_arg.C_addr));
107	
108	    std::vector<TYPE> h_A(size_sq), h_B(size_sq), h_C(size_sq);
109	    for (uint32_t i = 0; i < size_sq; ++i) {
110	        h_A[i] = static_cast<TYPE>(std::rand()) / RAND_MAX;
111	        h_B[i] = static_cast<TYPE>(std::rand()) / RAND_MAX;
112	    }
113	
114	    auto t0 = std::chrono::high_resolution_clock::now();
115	
116	    CHECK(vx_enqueue_write(q, A_buf, 0, h_A.data(), buf_size, 0,nullptr,nullptr));
117	    CHECK(vx_enqueue_write(q, B_buf, 0, h_B.data(), buf_size, 0,nullptr,nullptr));
118	
119	    vx_launch_info_t li{};
120	    li.struct_size = sizeof(li);
121	    li.kernel      = kern;
122	    li.args_host   = &kernel_arg;
123	    li.args_size   = sizeof(kernel_arg);
124	    li.ndim        = 2;
125	    li.grid_dim[0] = grid[0];  li.grid_dim[1] = grid[1];
126	    li.block_dim[0]= block[0]; li.block_dim[1]= block[1];
127	
128	    vx_event_h launch_ev=nullptr, read_ev=nullptr;
129	    CHECK(vx_enqueue_launch(q, &li, 0, nullptr, &launch_ev));
130	    CHECK(vx_enqueue_read(q, h_C.data(), C_buf, 0, buf_size,
131	                          1, &launch_ev, &read_ev));
132	    CHECK(vx_event_wait_value(read_ev, 1, VX_TIMEOUT_INFINITE));
133	    auto t1 = std::chrono::high_resolution_clock::now();
134	    std::printf("Elapsed: %ld ms\n",
135	        (long)std::chrono::duration_cast<std::chrono::milliseconds>(t1-t0).count());
136	
137	    int errors = 0;
138	    std::vector<TYPE> h_ref(size_sq);
139	    matmul_cpu(h_ref.data(), h_A.data(), h_B.data(), size);
140	    for (uint32_t i = 0; i < size_sq; ++i) {
141	        if (!float_eq(h_C[i], h_ref[i])) {
142	            if (errors < 16)
143	                std::printf("*** [%u] expected=%f actual=%f\n", i, h_ref[i], h_C[i]);
144	            ++errors;
145	        }
146	    }
147	
148	    vx_event_release(read_ev);
149	    vx_event_release(launch_ev);
150	    vx_buffer_release(C_buf);
151	    vx_buffer_release(B_buf);
152	    vx_buffer_release(A_buf);
153	    vx_kernel_release(kern);
154	    vx_module_release(mod);
155	    vx_queue_release(q);
156	    vx_device_dump_perf(dev, stdout);
157	    vx_device_release(dev);
158	
159	    if (errors) {
160	        std::cout << "Found " << errors << " errors!\nFAILED!" << std::endl;
161	        return errors;
162	    }
163	    std::cout << "PASSED!" << std::endl;
164	    return 0;
165	}
